#!/usr/bin/env python3
"""Generate ISO 4217 minor units from SIX List One XML supplied as a file."""

import pathlib
import sys
import xml.etree.ElementTree as ET


def main():
    root = ET.parse(sys.argv[1]).getroot()
    units = {}
    for entry in root.findall("./CcyTbl/CcyNtry"):
        code = entry.findtext("Ccy")
        if not code:
            continue
        minor = entry.findtext("CcyMnrUnts")
        units[code] = int(minor) if minor and minor.isdigit() else -1

    lines = [
        "// Code generated by scripts/generate-currency-units.py; DO NOT EDIT.",
        f"// Source: SIX ISO 4217 List One, published {root.attrib['Pblshd']}.",
        "package format",
        "",
        "var currencyMinorUnits = map[string]int{",
    ]
    lines.extend(f'\t"{code}": {units[code]},' for code in sorted(units))
    lines.extend(["}", ""])
    target = pathlib.Path(__file__).resolve().parents[1] / "internal/engine/l10n/format/currency_units.go"
    target.write_text("\n".join(lines))


if __name__ == "__main__":
    main()
